sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.fds-home-container {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  padding: 20px;
  color: black;
}

.fds-hero-banner {
  
  background-color: #f8f8f8;
  text-align: center;
  padding: 40px 20px;
  border-radius: 12px;
  margin-bottom: 30px;
  color: black;
}

.fds-hero-banner h1 {
  font-size: 28px;
  color: black;
  margin-bottom: 10px;
}

.fds-hero-banner p {
  font-size: 16px;
  color: black;
}

.fds-action-card {
  background: #ffffff;
  padding: 30px;
  max-width: 500px;
  margin: 0 auto 40px auto;
  border-radius: 12px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
  text-align: center;
}

.fds-action-card .card-content i {
  font-size: 40px;
  color: black;
  margin-bottom: 10px;
}

.fds-action-card .card-content h2 {
  color: black;
  margin: 10px 0;
}

.fds-action-card .card-content p {
  color: black;
  margin-bottom: 20px;
}

.fds-action-card button {
  background-color: black;
  color: #fff;
  border: none;
  padding: 12px 25px;
  border-radius: 8px;
  cursor: pointer;
  font-size: 16px;
  transition: background-color 0.3s ease;
}

.fds-action-card button:hover {
  background-color: #333;
}

.fds-process-tracker {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 20px;
}

.fds-process-tracker .step {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.fds-process-tracker .step i {
  font-size: 28px;
  color: black;
  margin-bottom: 5px;
}

.fds-process-tracker .step p {
  font-size: 14px;
  color: black;
}

.fds-process-tracker .tracker-line {
  width: 30px;
  height: 2px;
  background-color: black;
}
